      game.nearest = () => ({ text: 'Carry', run() {}, alt: { text: 'Gut', hold: 0.3, run: () => ran.push(1) } });
      key('keydown'); game.busy = true; game.prompts.tick(game.nearest()); game.busy = false; check(!P.held, 'a dialogue does not cancel it');
