        T += 3.2; n++; left++; const got = stackPrice({ id, n: 1, g: kg * 1000, day: CATCH.hooks.today() }); coins += got; flat[0] += priceOf(id); flat[1] += got; flat[2] += priceOf(id) * kg / FW.kgOf(f, f.cm[0] + (f.cm[1] - f.cm[0]) / 4); if (n % 30 === 0) T += 120;
