      check(Bo().dirt === 0 && Bo().mud === 0 && Bo().blood === 0 && I.count('soap') === 1 && Bo().fresh && p().pose?.kind === 'bath', `at 12 s: dirt ${Bo().dirt}, soap ${I.count('soap')}, fresh ${Bo().fresh}, pose ${p().pose?.kind}`);
