      live.receive('tb1', { t: 'hi', id: '~tb1', name: 'Bañista', playing: true, look: LOOK });
      live.receive('tb1', { t: 'st', sc: 'world', x: spot[0], y: spot[1], yaw: 0, po: [0, 0, 0.12], ba: 1 });
