      b.beardGrows = false; check(b.growth().beardStep === 0, 'beardGrows false still grows'); b.beardGrows = true;
      p().look = { ...lookWas, sex: 'chica' }; check(b.growth().beardStep === 0, 'a female body grows a beard');
