    at(l, x, y) { return this[l]?.[`${x},${y}`]; }, pieceAt(x, y) { const v = this.placed[`${x},${y}`]; return v && PIECES[parsePlaced(v)[0]]; },
    roofAt(x, y) { return !!this.roof[`${x},${y}`]; }, doorClosed(x, y) { return !!this.closed[`${x},${y}`]; }, lightOff(x, y) { return !!this.off[`${x},${y}`]; },
