        const q = rec({ q: Math.max(0, Q), gut: now - 1, size, f: (id === 'carcass_deer' && R() < 7 / 12 ? QL.F.ANTLERS : 0) | (gut ? QL.F.TAINTED : 0) });   // (the antlers, seven months of twelve)
