    const S = game.social, said = [], toasts = [], say = S.say.bind(S), toast = hud.toast;
    S.say = (e, text, o) => { said.push([e, text]); say(e, text, o); }; hud.toast = (m, k) => { toasts.push(m); toast(m, k); };
